public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
        throws IOException, ServletException {
    HttpServletRequest r = (HttpServletRequest) req;
    String key = r.getMethod() + " " + r.getRequestURI() + " " + r.getHeader("Accept-Encoding");
    CachedPage hit = store.getIfPresent(key);           // Caffeine or JCache
    if (hit != null) { hit.writeTo((HttpServletResponse) res); return; }
    CapturingResponse capture = new CapturingResponse((HttpServletResponse) res);
    chain.doFilter(req, capture);                       // origin path on a miss
    store.put(key, capture.toPage(TTL));                // only GET/HEAD 200s
    capture.writeTo((HttpServletResponse) res);
}

