@Cacheable(cacheNames = "pages", key = "#slug + '|' + #locale")
public String renderArticlePage(String slug, Locale locale) {
    // called by the controller; no request or response object involved
    return templates.render("article", articles.bySlug(slug));
}

@CacheEvict(cacheNames = "pages", allEntries = true)
